def test_module_imports():
    assert solution is not None


def test_example():
    assert split_two_parts([1, 1, 2, 3, 4, 4, 5, 1], 3) == ([1, 1, 2], [3, 4, 4, 5, 1])


def test_returns_tuple_of_two_lists():
    result = split_two_parts([1, 2, 3], 1)
