    assert len(result) == 2
    assert result == ([1], [2, 3])


def test_zero_length_first_part():
    assert split_two_parts([1, 2, 3], 0) == ([], [1, 2, 3])


def test_first_part_full_length():
    assert split_two_parts([1, 2, 3], 3) == ([1, 2, 3], [])


def test_first_part_longer_than_list():
    assert split_two_parts([1, 2, 3], 5) == ([1, 2, 3], [])


def test_empty_list():
    assert split_two_parts([], 0) == ([], [])
    assert split_two_parts([], 3) == ([], [])


def test_does_not_mutate_input():
    original = [1, 2, 3, 4]
    split_two_parts(original, 2)
    assert original == [1, 2, 3, 4]
